<script>
const aiThinkingLabel = <?= json_encode(\App\Core\Locale::text('AI is thinking')) ?>;
const setAiThinking = (form) => {
    if (form.dataset.aiLoading) return;
    const button = form.querySelector('button:not([type]), button[type="submit"]');
    if (!button) return;
    form.dataset.aiLoading = '1';
    button.disabled = true;
    button.innerHTML = `<span class="ai-thinking">${aiThinkingLabel} <i></i><i></i><i></i></span>`;
};
document.querySelectorAll('[data-format]').forEach((button) => button.addEventListener('click', () => {
    document.execCommand(button.dataset.format, false, button.dataset.value || null);
    document.getElementById(button.dataset.editorTarget || 'slide-editor').focus();
}));
document.querySelectorAll('[data-studio-tab]').forEach((button) => button.addEventListener('click', () => {
    document.querySelectorAll('[data-studio-tab]').forEach((tab) => tab.classList.toggle('is-active', tab === button));
    document.querySelectorAll('[data-studio-panel]').forEach((panel) => panel.hidden = panel.dataset.studioPanel !== button.dataset.studioTab);
}));
document.querySelectorAll('[data-insert-image]').forEach((button) => button.addEventListener('click', () => {
    button.closest('.editor-toolbar').querySelector(`[data-inline-image-input="${button.dataset.editorTarget}"]`).click();
}));
document.querySelectorAll('[data-inline-image-input]').forEach((input) => input.addEventListener('change', async () => {
    const image = input.files[0];
    if (!image) return;
    const form = input.closest('form');
    const data = new FormData();
    data.append('_token', form.querySelector('[name="_token"]').value);
    data.append('course_id', form.dataset.courseId);
    data.append('image', image);
    try {
        const response = await fetch(<?= json_encode(\App\Core\Request::basePath()) ?> + '/teacher/inline-image', {method: 'POST', body: data});
        const result = await response.json();
        if (!response.ok || !result.url) throw new Error();
        const editor = document.getElementById(input.dataset.inlineImageInput);
        editor.focus();
        document.execCommand('insertImage', false, result.url);
    } catch {
        window.alert('The image could not be uploaded. Use a JPEG, PNG, WebP, or GIF image up to 25 MB.');
    } finally {
        input.value = '';
    }
}));
document.querySelectorAll('[data-editor-form]').forEach((form) => form.addEventListener('submit', () => {
    document.getElementById(form.dataset.contentTarget).value = document.getElementById(form.dataset.editorTarget).innerHTML;
    if (form.dataset.aiCheckbox && form.querySelector(`[name="${form.dataset.aiCheckbox}"]`).checked) setAiThinking(form);
}));
document.querySelectorAll('form[data-ai-form]').forEach((form) => form.addEventListener('submit', () => setAiThinking(form)));
document.querySelectorAll('.question-type').forEach((select) => select.addEventListener('change', () => {
    const form = select.closest('form');
    const choices = form.querySelector('.choice-fields');
    const isText = select.value === 'TEXT';
    choices.hidden = isText;
    choices.querySelectorAll('input[name="options[]"]').forEach((input, index) => input.required = !isText && index < 2);
    choices.querySelectorAll('.correct-option').forEach((input) => input.type = select.value === 'CHECKBOX' ? 'checkbox' : 'radio');
}));
</script>
